logo_sparkle_recipe.css_keyframes:
@keyframes logoShimmerSweep { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
@keyframes sparkleFloat1 { 0%, 100% { transform: translate(0, 0) scale(0.6); opacity: 0.2; } 50% { transform: translate(-6px, -10px) scale(1.1); opacity: 1; } }
@keyframes sparkleFloat2 { 0%, 100% { transform: translate(0, 0) scale(0.5); opacity: 0.3; } 50% { transform: translate(8px, -12px) scale(1.2); opacity: 0.9; } }
@keyframes sparkleFloat3 { 0%, 100% { transform: translate(0, 0) scale(0.7); opacity: 0.1; } 50% { transform: translate(4px, -8px) scale(1); opacity: 0.95; } }
@media (prefers-reduced-motion: reduce) { .logo-sparkle-anim, .sparkle-particle { animation: none !important; } }
